SubWidgetExt = mod.SubWidgetExt.SubWidgetExt
TDF = op.TDModules.mod.TDFunctions

class RadioExt(SubWidgetExt):
	"""
	RadioExt description
	"""
	def __init__(self, ownerComp):
		# The component to which this extension is attached
		self.parPrefix = 'Radio'
		SubWidgetExt.__init__(self, ownerComp)

	def onPanelEvent(self, event, panelValue):
		if event == 'offToOn':
			setattr(parent.Widget.par, 'Value'+str(self.ownerComp.digits),
					panelValue.owner.digits)

	def onParSettingsChange(self, par, prev):
		"""
		Manages value changes widget settings parameters
		"""
		val = par.eval()
		if par.name in ['Minmax01', 'Minmax02', 'Default0']:
			self.ownerComp.op('replicator1').par.recreateall.pulse()
		else:
			SubWidgetExt.onParSettingsChange(self, par, prev)

	def makePanelExecute(self):
		SubWidgetExt.makePanelExecute(self,
					"me.dock.op('" + self.ownerComp.name +"').path + '/radio*'")

